// ── workflow_lifecycle_v1: a .ron workflow run opened ─────────────
// Schema: schema/core-event.schema.json, alternative `type: 'workflow_started'`.
// required: type, workflow_id, name, node_count, run_id, event_id, sequence
| {
    type: 'workflow_started';
    /** Stable id of the workflow definition, e.g. `desktop-audit`. */
    workflow_id: string;
    /** Human-readable display name, e.g. `Desktop audit`. */
    name: string;
    /** Declared node count for this run. Fixtures show 0 and 1; not a bound. */
    node_count: number;
    /** Correlation key for the whole run; pairs with `sequence`. */
    run_id: string;
    /** Idempotency key. Same id + same body = replay; same id + different body = conflict. */
    event_id: string;
    /** Monotonic per-run counter. Only the three workflow_* types advance it. */
    sequence: number;
    /** Present only when this run was spawned by another run. Optional in the schema. */
    parent_run_id?: string;
  }

// ── workflow_lifecycle_v1: one node's state transition ────────────
// required: type, run_id, node_id, event_id, sequence, state
| {
    type: 'workflow_node_event';
    run_id: string;
    /** Node identifier within the workflow definition, e.g. `scan`. */
    node_id: string;
    event_id: string;
    sequence: number;
    /** Exactly these five values; `blocked` appears in the schema enum only. */
    state: 'queued' | 'running' | 'succeeded' | 'failed' | 'blocked';
    /** The sub-agent run executing this node; joins to sub_agent_event.child_run_id. Optional. */
    child_run_id?: string;
    /** Present on failure. All three inner fields are required when `failure` is present. */
    failure?: { code: string; message: string; retryable: boolean };
  }

// ── workflow_lifecycle_v1: the run reached a terminal state ───────
// required: type, workflow_id, succeeded, run_id, event_id, sequence, terminal_state
| {
    type: 'workflow_finished';
    workflow_id: string;
    /** Redundant with `terminal_state`; the contract requires both. Do not derive one from the other. */
    succeeded: boolean;
    run_id: string;
    event_id: string;
    sequence: number;
    /** Only two values here - `blocked` is a node state, not a run state. */
    terminal_state: 'succeeded' | 'failed';
    failure?: { code: string; message: string; retryable: boolean };
  }

// REPLACES the existing sub_agent_event member at protocol.ts:164-170.
// The schema has TWO alternatives for this type: an authoritative one that
// REQUIRES run_id/child_run_id/child_sequence/event_id, and one titled
// "Legacy non-authoritative sub-agent compatibility event" whose `not` clause
// FORBIDS all of them. Darhai today models only the legacy shape. The five
// fields are therefore optional in TS and a runtime guard decides which
// alternative a given payload satisfies; treating them as always-present
// would break the legacy stream, treating them as never-present is what
// currently makes 2 of this capability's 8 fixtures undrivable.
| {
    type: 'sub_agent_event';
    parent_call_id: string;
    agent_name: string;
    /** Serialized inner WCoreEvent from the sub-agent; opaque to the host. */
    inner: unknown;
    /** Durable alternative only: the parent workflow run. */
    run_id?: string;
    /** Durable alternative only: correlation key for this child's own stream. */
    child_run_id?: string;
    /** Durable alternative only: monotonic per-child counter, starts at 0. */
    child_sequence?: number;
    /** Durable alternative only: idempotency key for this child event. */
    event_id?: string;
    /** Nesting link when a child spawns its own child. */
    parent_child_run_id?: string;
    /** Present on the child's final event. When 'succeeded' the schema constrains
     *  inner to {type:'info', msg_id, message}; when 'failed', to
     *  {type:'error', error:{code,message,retryable}}. */
    terminal_state?: 'succeeded' | 'failed';
  }
